void solve() {
    int n = nextInt();
    int[] a = new int[n];
    for (int i = 0; i < n; i++) {
        a[i] = nextInt();
    }
    long res = 0;
    List<List<Integer>> occ = new ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) {
        List<Integer> innerList = new ArrayList<>();
        innerList.add(-1);
        occ.add(innerList);
    }
    MinValSegTree tree = new MinValSegTree(n);
    for (int i = 0; i < n; i++) {
        List<Integer> l1 = occ.get(a[i]);
        int p1 = l1.get(l1.size() - 1);
        if (l1.size() >= 2) {
            int p2 = l1.get(l1.size() - 2);
            tree.add(p2 + 1, p1, -1);
        }
        l1.add(i);
        tree.add(p1 + 1, i, 1);
        MinValSegTree.Node node = tree.queryMin(0, i);
        res += i + 1 - (node.minVal == 0 ? node.minFreq : 0);
    }
    System.out.println(res);
}

